async function generateExcelReport(data, outputPath) {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'thepopebot Financial System';
  workbook.created = new Date();

  // ===== SUMMARY SHEET =====
  const summary = workbook.addWorksheet('Summary');

  // Title
  summary.mergeCells('A1:D1');
  summary.getCell('A1').value = 'Daily Financial Report';
  summary.getCell('A1').font = { size: 16, bold: true };
  summary.getCell('A1').alignment = { horizontal: 'center' };

  summary.mergeCells('A2:D2');
  summary.getCell('A2').value = `Report Date: ${data.date}`;
  summary.getCell('A2').alignment = { horizontal: 'center' };

  // Key Metrics Table
  summary.addRow([]);
  summary.addRow(['Metric', 'Amount', 'Change (DoD)', 'Change (7-Day)']);
  summary.getRow(4).font = { bold: true };

  summary.addRow(['Total Revenue', `$${data.revenue.toFixed(2)}`, data.revenueDod, data.revenue7d]);
  summary.addRow(['Total Expenses', `$${data.expenses.toFixed(2)}`, data.expensesDod, data.expenses7d]);
  summary.addRow(['Net Income', `$${data.netIncome.toFixed(2)}`, data.netIncomeDod, data.netIncome7d]);
  summary.addRow(['Cash Balance (Est.)', `$${data.cashBalance.toFixed(2)}`, data.cashDod, data.cash7d]);

  // Operational Metrics
  summary.addRow([]);
  summary.addRow(['Operational Metrics']);
  summary.getRow(9).font = { bold: true };

  summary.addRow(['New Invoices', data.newInvoices, `$${data.newInvoicesAmount.toFixed(2)}`]);
  summary.addRow(['Overdue Invoices', data.overdueInvoices, `$${data.overdueAmount.toFixed(2)}`]);
  summary.addRow(['Collection Rate', `${data.collectionRate}%`]);
  summary.addRow(['Avg Transaction', `$${data.avgTransaction.toFixed(2)}`]);

  // Column widths
  summary.getColumn(1).width = 30;
  summary.getColumn(2).width = 15;
  summary.getColumn(3).width = 15;
  summary.getColumn(4).width = 15;

  // ===== TRANSACTIONS SHEET =====
  const transactions = workbook.addWorksheet('Transactions');
  transactions.columns = [
    { header: 'Date', key: 'date', width: 12 },
    { header: 'Type', key: 'type', width: 12 },
    { header: 'Category', key: 'category', width: 20 },
    { header: 'Description', key: 'description', width: 35 },
    { header: 'Amount', key: 'amount', width: 15 },
    { header: 'Status', key: 'status', width: 12 },
    { header: 'Notes', key: 'notes', width: 25 }
  ];

  transactions.getRow(1).font = { bold: true };
  data.transactions.forEach(t => transactions.addRow(t));

  // ===== REVENUE SHEET =====
  const revenue = workbook.addWorksheet('Revenue');
  revenue.columns = [
    { header: 'Category', key: 'name', width: 25 },
    { header: 'Amount', key: 'amount', width: 15 },
    { header: 'Percentage', key: 'pct', width: 12 }
  ];

  revenue.getRow(1).font = { bold: true };
  data.revenueCategories.forEach(cat => {
    revenue.addRow({
      name: cat.name,
      amount: `$${cat.amount.toFixed(2)}`,
      pct: `${cat.pct.toFixed(1)}%`
    });
  });

  revenue.addRow({});
  revenue.addRow({
    name: 'TOTAL',
    amount: `$${data.revenue.toFixed(2)}`,
    pct: '100.0%'
  }).font = { bold: true };

  // ===== EXPENSES SHEET =====
  const expenses = workbook.addWorksheet('Expenses');
  expenses.columns = [
    { header: 'Category', key: 'name', width: 25 },
    { header: 'Amount', key: 'amount', width: 15 },
    { header: 'Percentage', key: 'pct', width: 12 }
  ];

  expenses.getRow(1).font = { bold: true };
  data.expenseCategories.forEach(cat => {
    expenses.addRow({
      name: cat.name,
      amount: `$${cat.amount.toFixed(2)}`,
      pct: `${cat.pct.toFixed(1)}%`
    });
  });

  expenses.addRow({});
  expenses.addRow({
    name: 'TOTAL',
    amount: `$${data.expenses.toFixed(2)}`,
    pct: '100.0%'
  }).font = { bold: true };

  // ===== CASH FLOW SHEET =====
  const cashflow = workbook.addWorksheet('Cash Flow');
  cashflow.columns = [
    { header: 'Component', key: 'component', width: 30 },
    { header: 'Amount', key: 'amount', width: 15 },
    { header: 'Notes', key: 'notes', width: 35 }
  ];

  cashflow.getRow(1).font = { bold: true };
  cashflow.addRow({
    component: 'Opening Balance',
    amount: `$${data.openingBalance.toFixed(2)}`,
    notes: `Balance as of previous day close`
  });
  cashflow.addRow({
    component: 'Cash In (Revenue)',
    amount: `+$${data.cashIn.toFixed(2)}`,
    notes: `Total revenue collected`
  });
  cashflow.addRow({
    component: 'Cash Out (Expenses)',
    amount: `-$${data.cashOut.toFixed(2)}`,
    notes: `Total expenses paid`
  });
  cashflow.addRow({
    component: 'Net Change',
    amount: `$${data.netChange.toFixed(2)}`,
    notes: `Revenue minus expenses`
  }).font = { bold: true };
  cashflow.addRow({
    component: 'Closing Balance',
    amount: `$${data.closingBalance.toFixed(2)}`,
    notes: `Estimated end-of-day balance`
  }).font = { bold: true };

  await workbook.xlsx.writeFile(outputPath);
  console.log(`✅ Excel report saved: ${outputPath}`);
}

async function generateCSVReport(data, outputPath) {
  const headers = 'Date,Type,Category,Description,Amount,Status,Notes\n';
  const rows = data.transactions.map(t => 
    `${t.date},${t.type},${t.category},"${t.description}",${t.amount},${t.status},"${t.notes}"`
  ).join('\n');

  fs.writeFileSync(outputPath, headers + rows);
  console.log(`✅ CSV file saved: ${outputPath}`);
}

async function generatePDFReport(data, outputPath) {
  const doc = new PDFDocument({ 
    size: 'LETTER', 
    margin: 50,
    info: {
      Title: `Financial Report - ${data.date}`,
      Author: 'thepopebot Financial System'
    }
  });

  doc.pipe(fs.createWriteStream(outputPath));

  // Title
  doc.fontSize(20).text('Daily Financial Summary', { align: 'center' });
  doc.fontSize(11).text(`Report Date: ${data.date}`, { align: 'center' });
  doc.fontSize(9).text(`Generated: ${new Date().toISOString()}`, { align: 'center' });
  doc.moveDown(1.5);

  // Key Metrics Box
  doc.rect(50, doc.y, 500, 100).stroke();
  doc.fontSize(12).text('Key Financial Metrics', 60, doc.y + 10);
  doc.fontSize(10)
     .text(`Revenue: $${data.revenue.toFixed(2)}  (${data.revenueDod})`, 60, doc.y + 30)
     .text(`Expenses: $${data.expenses.toFixed(2)}  (${data.expensesDod})`, 60, doc.y)
     .text(`Net Income: $${data.netIncome.toFixed(2)}  (${data.netIncomeDod})`, 60, doc.y)
     .text(`Cash Balance: $${data.cashBalance.toFixed(2)}  (${data.cashDod})`, 60, doc.y);

  doc.moveDown(3);

  // Revenue Breakdown
  doc.fontSize(12).text('Top Revenue Categories', { underline: true });
  doc.fontSize(9);
  data.revenueCategories.filter(c => c.amount > 0).forEach(cat => {
    doc.text(`  • ${cat.name}: $${cat.amount.toFixed(2)} (${cat.pct.toFixed(1)}%)`);
  });

  doc.moveDown(1);

  // Expense Breakdown
  doc.fontSize(12).text('Top Expense Categories', { underline: true });
  doc.fontSize(9);
  data.expenseCategories.filter(c => c.amount > 0).forEach(cat => {
    doc.text(`  • ${cat.name}: $${cat.amount.toFixed(2)} (${cat.pct.toFixed(1)}%)`);
  });

  doc.moveDown(1);

  // Cash Flow
  doc.fontSize(12).text('Cash Flow', { underline: true });
  doc.fontSize(9)
     .text(`  Opening Balance: $${data.openingBalance.toFixed(2)}`)
     .text(`  Cash In: +$${data.cashIn.toFixed(2)}`)
     .text(`  Cash Out: -$${data.cashOut.toFixed(2)}`)
     .text(`  Net Change: $${data.netChange.toFixed(2)}`)
     .text(`  Closing Balance: $${data.closingBalance.toFixed(2)}`);

  doc.moveDown(1);

  // Accounts Receivable
  doc.fontSize(12).text('Accounts Receivable', { underline: true });
  doc.fontSize(9)
     .text(`  Total Outstanding: $${data.arTotal.toFixed(2)}`)
     .text(`  0-30 Days: $${data.ar0to30.toFixed(2)} (${data.ar0to30Count} invoices)`)
     .text(`  31-60 Days: $${data.ar31to60.toFixed(2)} (${data.ar31to60Count} invoices)`)
     .text(`  60+ Days: $${data.ar60plus.toFixed(2)} (${data.ar60plusCount} invoices)`);

  doc.moveDown(1);

  // Data Limitations
  doc.fontSize(10).text('Data Quality & Limitations', { underline: true });
  doc.fontSize(8);
  data.limitations.forEach(limit => {
    doc.text(`  ⚠ ${limit}`);
  });

  doc.moveDown(0.5);

  // Disclaimer
  doc.fontSize(7).text(
    'This report is generated by an automated system using publicly available data and estimates. ' +
    'It does not constitute financial advice or a substitute for professional accounting. ' +
    'Data may be incomplete, delayed, or inaccurate. Always consult qualified financial professionals ' +
    'for business financial decisions.',
    { align: 'center', color: '#666666' }
  );

  doc.end();
  console.log(`✅ PDF summary saved: ${outputPath}`);
}

// Main execution
(async () => {
  try {
    const reportDate = getReportDate();
    console.log(`\n📊 Generating Daily Financial Report for: ${reportDate}\n`);

    const data = generateSampleData(reportDate);
    const reportDir = `/job/logs/daily_reports/${reportDate}`;

    // Create directory
    fs.mkdirSync(reportDir, { recursive: true });
    console.log(`📁 Created directory: ${reportDir}\n`);

    // Generate all reports
    await generateExcelReport(data, path.join(reportDir, 'report.xlsx'));
    await generateCSVReport(data, path.join(reportDir, 'transactions.csv'));
    await generatePDFReport(data, path.join(reportDir, 'summary.pdf'));

    console.log(`\n✅ All reports generated successfully!`);
    console.log(`📂 Location: ${reportDir}\n`);

    // Summary output
    console.log('📈 Report Summary:');
    console.log(`   Revenue: $${data.revenue.toFixed(2)} (${data.revenueDod})`);
    console.log(`   Expenses: $${data.expenses.toFixed(2)} (${data.expensesDod})`);
    console.log(`   Net Income: $${data.netIncome.toFixed(2)} (${data.netIncomeDod})`);
    console.log(`   Cash Balance: $${data.cashBalance.toFixed(2)}`);
    console.log(`   Transactions: ${data.transactions.length} items\n`);

  } catch (error) {
    console.error('❌ Error generating reports:', error);
    process.exit(1);
  }
})();

